using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;
namespace LWS.TruckDanceOff.Editor {
public static class DancePresentationAuthoring {
 public static void Upgrade(){var scene=EditorSceneManager.OpenScene(DanceAuthoring.Scene);Install(UnityEngine.Object.FindAnyObjectByType<DanceMatch>());EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 static void Text(TMPro.TMP_Text t,Vector2 pos,Vector2 size,int font){t.rectTransform.anchoredPosition=pos;t.rectTransform.sizeDelta=size;t.fontSize=font;t.fontSizeMax=font;t.fontSizeMin=font*.85f;}
 public static void Install(DanceMatch m){var h=m.rhythmHud;h.arrows=new Sprite[4];for(int lane=0;lane<4;lane++)h.arrows[lane]=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Heat - Complete Modern UI/Textures/Icons/Navigation/Arrow "+new[]{"Left","Bottom","Top","Right"}[lane]+" (64x).png");
  for(int i=0;i<h.strips.Length;i++){var s=h.strips[i];s.root.sizeDelta=new Vector2(340,370);s.root.anchoredPosition=new Vector2((i-1.5f)*370,-310);s.root.GetComponent<Image>().color=new Color(.008f,.014f,.035f,.76f);var plate=s.root.GetComponent<SportsBroadcastPlate>()??s.root.gameObject.AddComponent<SportsBroadcastPlate>();plate.cut=13;Text(s.title,new Vector2(0,150),new Vector2(320,32),24);Text(s.combo,new Vector2(0,115),new Vector2(320,32),27);Text(s.routine,new Vector2(0,85),new Vector2(320,22),17);Text(s.judgment,new Vector2(0,-138),new Vector2(320,32),24);Text(s.controls,new Vector2(0,-167),new Vector2(320,22),16);
   var field=(RectTransform)s.root.Find("Clipped note field");field.sizeDelta=new Vector2(310,190);field.anchoredPosition=new Vector2(0,-25);for(int lane=0;lane<4;lane++){var rec=s.receptors[lane].rectTransform;rec.localRotation=Quaternion.identity;rec.sizeDelta=new Vector2(34,34);rec.anchoredPosition=new Vector2((lane-1.5f)*68,-80);s.receptors[lane].sprite=h.arrows[lane];s.receptors[lane].preserveAspect=true;var rail=(RectTransform)field.Find("Lane "+lane);rail.sizeDelta=new Vector2(2,180);rail.anchoredPosition=new Vector2((lane-1.5f)*68,0);}foreach(var note in s.notes)note.localRotation=Quaternion.identity;foreach(var face in s.faces)face.preserveAspect=true;
  }
  var camera=m.stageCamera.GetComponent<SportsEventCamera>();camera.Pose(new Vector3(0,0,-5),new Vector3(0,12,-23),52,true);m.stageCamera.clearFlags=CameraClearFlags.SolidColor;m.stageCamera.backgroundColor=new Color(.007f,.009f,.025f);RenderSettings.skybox=null;RenderSettings.ambientLight=new Color(.22f,.24f,.35f);RenderSettings.fogColor=new Color(.012f,.013f,.04f);foreach(var light in UnityEngine.Object.FindObjectsByType<Light>())if(light.type==LightType.Directional){light.intensity=.9f;light.color=new Color(.75f,.8f,1);}
  foreach(var text in m.menus.pages[4].GetComponentsInChildren<TMPro.TMP_Text>(true))if(text.name=="Rules and controls")text.text=m.Help;DanceStageEffectsAuthoring.Install(m);EditorUtility.SetDirty(h);EditorUtility.SetDirty(m);Debug.Log("DANCE_PRESENTATION_SAFE compact bottom charts, directional Heat arrows, readable truck stage and midnight background");
 }
}
}
